package com.tripsync.service;
import com.tripsync.dto.ApiDtos.*; import com.tripsync.entity.*; import com.tripsync.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException;
import software.amazon.awssdk.services.s3.model.PutObjectRequest; import software.amazon.awssdk.services.s3.model.GetObjectRequest; import software.amazon.awssdk.services.s3.presigner.model.GetObjectPresignRequest; import software.amazon.awssdk.services.s3.presigner.S3Presigner; import software.amazon.awssdk.services.s3.presigner.model.PutObjectPresignRequest;
import java.time.*; import java.util.*;
@Service public class MediaService {
 private final MediaAssetRepository media; private final ShareLinkRepository links; private final TripService trips; private final S3Presigner presigner; @Value("${app.s3.bucket}") String bucket;
 public MediaService(MediaAssetRepository m,ShareLinkRepository l,TripService t,S3Presigner p){media=m;links=l;trips=t;presigner=p;}
 public UploadResponse createUpload(UUID groupId,UploadRequest r,String user){trips.requireMember(groupId,user);if(r.sizeBytes()>500_000_000L)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"MVP upload limit is 500 MB");
  if(!r.contentType().startsWith("image/")&&!r.contentType().startsWith("video/"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Only image and video files are supported");
  MediaAsset a=new MediaAsset();a.setGroupId(groupId);a.setUploaderId(user);a.setFileName(r.fileName());a.setContentType(r.contentType());a.setSizeBytes(r.sizeBytes());a.setCapturedAt(r.capturedAt());a.setLatitude(r.latitude());a.setLongitude(r.longitude());a.setCameraMake(r.cameraMake());a.setCameraModel(r.cameraModel());a.setAperture(r.aperture());a.setShutterSpeed(r.shutterSpeed());a.setIso(r.iso());a.setFocalLength(r.focalLength());a.setObjectKey("groups/"+groupId+"/"+a.getId()+"/"+safeName(r.fileName()));media.save(a);
  var put=PutObjectRequest.builder().bucket(bucket).key(a.getObjectKey()).contentType(r.contentType()).build();var presign=presigner.presignPutObject(PutObjectPresignRequest.builder().signatureDuration(Duration.ofMinutes(15)).putObjectRequest(put).build());return new UploadResponse(a.getId(),presign.url().toString(),a.getObjectKey(),Instant.now().plusSeconds(900)); }
 private String safeName(String n){return n.replaceAll("[^a-zA-Z0-9._-]","_");}
 public MediaAsset complete(UUID id,String user){MediaAsset a=media.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));trips.requireMember(a.getGroupId(),user);if(!a.getUploaderId().equals(user))throw new ResponseStatusException(HttpStatus.FORBIDDEN);a.setStatus("READY");return media.save(a);}
 public List<MediaAsset> list(UUID groupId,String user){trips.requireMember(groupId,user);return media.findByGroupIdAndStatusOrderByCapturedAtDesc(groupId,"READY");}
 public String downloadUrl(UUID id,String user){MediaAsset a=media.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));trips.requireMember(a.getGroupId(),user);var get=GetObjectRequest.builder().bucket(bucket).key(a.getObjectKey()).build();return presigner.presignGetObject(GetObjectPresignRequest.builder().signatureDuration(Duration.ofMinutes(10)).getObjectRequest(get).build()).url().toString();}
 public ShareResponse share(UUID id,String user){MediaAsset a=media.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));trips.requireMember(a.getGroupId(),user);String token=UUID.randomUUID().toString().replace("-","")+UUID.randomUUID().toString().replace("-","");Instant exp=Instant.now().plus(Duration.ofDays(7));links.save(new ShareLink(token,id,exp));return new ShareResponse("/api/share/"+token,exp);}
 public ShareView resolveShare(String token){ShareLink l=links.findByToken(token).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(l.isRevoked()||l.getExpiresAt().isBefore(Instant.now()))throw new ResponseStatusException(HttpStatus.GONE,"Share link expired");MediaAsset a=media.findById(l.getMediaId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));var get=GetObjectRequest.builder().bucket(bucket).key(a.getObjectKey()).build();String url=presigner.presignGetObject(GetObjectPresignRequest.builder().signatureDuration(Duration.ofMinutes(10)).getObjectRequest(get).build()).url().toString();return new ShareView(a.getId(),a.getFileName(),a.getContentType(),url,l.getExpiresAt());}
}
